	/**
	 * 加载一个外部图片到当前上下文，方便后面使用。
	 * @param imageUrl 图片路径
	 * @param call 回调函数
	 * @example
	 * ```ts
	 * import { MxCpp, MxCADUiPrPoint } from "mxcad"
	 *
		async function Mx_Test_DrawImage() {
			const getPoint = new MxCADUiPrPoint();
			getPoint.setMessage("\n指定插入点:");
			let pt = await getPoint.go();
			if (!pt) return;
			let mxcad = MxCpp.getCurrentMxCAD();
			let imagUrl = "https://cdn.pixabay.com/photo/2022/11/15/12/23/winter-7593872_960_720.jpg";
			mxcad.loadImage(imagUrl, (image) => {
				if (!image) {
					console.log("loadImage failed");
					return;
				}
				let width = mxcad.mxdraw.viewCoordLong2Cad(100);
				let height = (image.height / image.width) * width;
				//let viewAngle = mxcad.mxdraw.getViewAngle() * 180  / Math.PI;
				//let viewAngle = mxcad.database.ucsMatrix.angleXYPlane() * 180  / Math.PI;
				//let viewAngle = 15.0;
				let viewAngle = 0.0;
				let id = mxcad.drawImage((pt as any).x, (pt as any).y, width, height, viewAngle, imagUrl, true, image.width, image.height);
				let ent = id.getMcDbEntity();
				if (ent) {
					ent.trueColor = new McCmColor(255, 255, 255, 160);
					// ent.rotate(pt,45 * 3.14159265 / 180.0);
				}
				mxcad.updateDisplay();
			});
		}
	 * ```
	 */
	loadImage(imageUrl: string, call: (image: any) => void, imageFileName?: string, fileType?: string): void;
	/**
	* 加载Base64图片。
	* @param imageUrl 图片路径
	* @param call 回调函数
	* @example
	* ```ts
		import { MxCpp } from "mxcad";
		function selectLocalFile() {
			return new Promise((resolve) => {
				const input = document.createElement("input");
				input.type = "file";
				input.accept = "image/*";
				input.onchange = (e) => resolve(e.target.files[0]);
				input.click();
			});
		}
		function fileToBase64(file) {
			return new Promise((resolve, reject) => {
				const reader = new FileReader();
				reader.onload = () => resolve(reader.result);
				reader.onerror = reject;
				reader.readAsDataURL(file);
			});
		}

		const file = await selectLocalFile();
		if (!file) return;
		const imagData = await fileToBase64(file);
		let mxcad = MxCpp.getCurrentMxCAD();

		mxcad.loadImageBase64(imagData, "test.jpg", (image) => {
			if (!image) {
				console.log("loadImage failed");
				return;
			}
			let width = mxcad.mxdraw.viewCoordLong2Cad(100);
			let height = (image.height / image.width) * width;

			let viewAngle = 0.0;
			let id = mxcad.drawImage(100, 100, width, height, viewAngle, "test.jpg", true, image.width, image.height,"",imagData);
			mxcad.updateDisplay();
		})
	* ```
	*/
	loadImageBase64(sImageBase64: string, imageFileName: string, call: (image: any) => void): void;
	/**
	 * 绘制一个图片
	 * @param dPosX 图片 X 坐标
	 * @param dPosY 图片 Y 坐标
	 * @param dWidth 图片宽度
	 * @param dHeight 图片高度
	 * @param dAng 图片角度,单位是度
	 * @param imageUrl 图片路径
	 * @example
	 * ```ts
	 * import { MxCpp } from "mxcad";
	 *
		async function Mx_Test_DrawImageBase64() {
			const getPoint = new MxCADUiPrPoint();
			getPoint.setMessage("\n指定插入点:");
			let pt = await getPoint.go();
			if (!pt) return;

			let mxcad = MxCpp.getCurrentMxCAD();
			let imagData = "data:image/jpeg;base64,";
			mxcad.loadImageBase64(imagData, "test.jpg", (image) => {
				if (!image) {
					console.log("loadImage failed");
					return;
				}
				let width = mxcad.mxdraw.viewCoordLong2Cad(100);
				let height = (image.height / image.width) * width;

				let viewAngle = 0.0;
				let id = mxcad.drawImage((pt as any).x, (pt as any).y, width, height, viewAngle, "test.jpg", false, image.width, image.height);
				let ent = id.getMcDbEntity();
				if (ent) {
					ent.trueColor = new McCmColor(255, 255, 255, 160);
				}
				mxcad.updateDisplay();
			});
		}
	 * ```
	 */
	drawImage(dPosX: number, dPosY: number, dWidth: number, dHeight: number, dAng: number, imageName: string, isConvertBase64?: boolean, dwgImageSizeWidth?: number, dwgImageSizeHeight?: number, imageUrl?: string, sImageBase64?: string): McObjectId;
	/**
	 * 将图片定义添加到 CAD 数据库中，供后续插入图片对象时复用。
	 *
	 * 该方法通常和 loadImage / drawImage 配合使用，先把图片资源加载到内存，
	 * 再把图片定义注册到数据库中，最后通过 drawImage 将图片真实插入到图纸中。
	 *
	 * @param imageUrl 图片地址。
	 * @param sName 图片定义名称。
	 * @param isConvertBase64 是否将图片转换为 Base64 数据。
	 * @param sourceFileName 图片源文件名。
	 * @param sBase64Data Base64 数据内容。
	 * @example
	 * ```ts
	 * import { MxCpp, McObject } from "mxcad";
	 *
	 * const mxcad: McObject = MxCpp.getCurrentMxCAD();
	 * const imagUrl = "https://cdn.pixabay.com/photo/2022/11/15/12/23/winter-7593872_960_720.jpg";
	 *
	 * mxcad.loadImage(imagUrl, (imagedata) => {
	 *   if (!imagedata) {
	 *     console.log("loadImage failed");
	 *     return;
	 *   }
	 *   mxcad.addImageDefine(imagUrl, "winter-7593872_960_720.jpg", true);
	 *   mxcad.updateDisplay();
	 * });
	 * ```
	 */
	addImageDefine(imageUrl: string, sName?: string, isConvertBase64?: boolean, sourceFileName?: string, sBase64Data?: string): McObjectId;
